            {"id": "beta", "proof": _proof(RT2, RT3)},
            {"id": "alpha", "proof": _proof(RT1, RT3)},
            {"id": "伽马", "proof": _proof(RT2, RT2)},
        ]
    )


def _expected(report):
    return {
        "root": report["root"],
        "proof_ids": [member["id"] for member in report["proofs"]],
    }


